function coach(){return `<svg class="coach" viewBox="0 0 320 380" aria-label="动作演示占位插画"><defs><linearGradient id="shirt" x2="1" y2="1"><stop stop-color="#9dbce5"/><stop offset="1" stop-color="#648fc7"/></linearGradient></defs><ellipse cx="160" cy="353" rx="80" ry="12" fill="#b7cee6" opacity=".5"/><g class="body"><path d="M145 220L125 333Q130 346 146 337L165 249L180 338Q193 346 201 332L181 217" fill="#2d4466"/><path d="M123 115Q160 93 195 116L188 230Q158 240 132 228Z" fill="url(#shirt)"/><g class="arm-left"><path d="M136 126Q109 137 93 111L70 81" fill="none" stroke="#87a9d7" stroke-width="24" stroke-linecap="round"/><path d="M70 81L60 68" stroke="#e7bfa9" stroke-width="17" stroke-linecap="round"/></g><g class="arm-right"><path d="M184 126Q214 144 237 120L259 98" fill="none" stroke="#7599cc" stroke-width="24" stroke-linecap="round"/><path d="M259 98L269 86" stroke="#e7bfa9" stroke-width="17" stroke-linecap="round"/></g><rect x="151" y="83" width="19" height="29" rx="8" fill="#dfb39d"/><ellipse cx="160" cy="69" rx="29" ry="35" fill="#edc8b3"/><path d="M131 69Q121 21 164 27Q199 25 189 70L181 50Q156 61 139 48Z" fill="#4c576d"/><path d="M130 338L112 350Q111 359 145 354L147 339M180 339L178 351Q187 360 214 352L200 337" fill="#f8fbff"/><path d="M151 79Q160 86 169 79" fill="none" stroke="#b78072" stroke-width="2"/></g></svg>`}
function staticPreview(c){return `<div class="static-preview static-preview-${c.id}" role="img" aria-label="${c.name}静态色块占位"><i></i><i></i><i></i></div>`}
function top(right=''){return `<div class="device-top"><span aria-hidden="true"></span>${right||'<span>社区运动空间</span>'}</div>`}
function back(target='home'){return `<button class="back" data-go="${target}">‹ 返回</button>`}
function current(){return activePool[idx]}
function cleanMedia(){mediaEpoch++;const v=D.querySelector('video');if(v){v.pause();v.removeAttribute('src');v.load()}}
function navigate(next){calendarOpen=false;clearTimeout(authTimer);clearTimeout(autoStartTimer);cleanMedia();screen=next;idle=0;if(next==='home'){session=null;paused=false}if(next==='video'||next==='image'){userId=null;authState='idle';session=null;paused=false}if(next==='video'){emptyOverride=false;activePool=C.pool(config);idx=0;mediaFailed.clear();initPreview();return}if(next==='image'){imageTime=0;imageIndex=0}render()}
function initPreview(){cleanMedia();previewTime=0;cycles=0;if(!activePool.length){preview=null;render();return}const c=current();const range=config.ranges[c.id]||c.preview;try{preview=C.slice({...c,duration:mediaLengths[c.id]||c.duration},range)}catch{mediaFailed.add(c.id);nextItem(1);return}render()}
function nextItem(delta){if(!activePool.length)return;let n=0;do{idx=(idx+delta+activePool.length)%activePool.length;n++}while(mediaFailed.has(current().id)&&n<=activePool.length);if(n>activePool.length){activePool=[];preview=null;render();return}initPreview()}
