function videoView(){const c=current();if(!c||emptyOverride)return `<div class="screen">${top('<span aria-hidden="true"></span>')}<div class="empty-state"><div class="big-icon">▤</div><h2>内容暂不可播放</h2><p>可以看看其他运动，<br>或稍后重新尝试。</p></div><button class="primary" data-go="home">看看其他运动</button><button class="secondary" id="retry-pool">重新尝试</button></div>`;return `<div class="screen immersive-video">${top('<span aria-hidden="true"></span>')}<div class="preview-heading"><h2>${c.name}</h2></div><div class="preview-card">${mediaURLs[c.id]?'<video id="preview-video" playsinline preload="auto"></video>':staticPreview(c)}<button class="sound" id="sound" aria-label="${muted?'开启':'关闭'}当前预览视频声音（不影响系统音量）" title="${muted?'开启':'关闭'}当前预览视频声音，不影响系统音量">${muted?'♪̸':'♪'}</button></div><div class="preview-bottom"><span id="preview-caption"></span><span id="preview-clock"></span></div><div class="preview-progress"><i id="preview-bar"></i></div><div class="switch-row"><button aria-label="上一个运动" id="previous" ${activePool.length<2?'disabled':''}>‹</button><button aria-label="下一个运动" id="next" ${activePool.length<2?'disabled':''}>›</button></div><div class="preview-actions"><button class="primary" id="start-preview" aria-label="一键跟练${c.name}">一键跟练</button><button class="secondary" data-go="home">看看其他运动</button></div></div>`}
function imageView(){const sources=config.images.length?config.images:['./assets/screensaver-fun-ai.jpg'],active=imageIndex%sources.length;return `<div class="screen image-screen" id="image-background"><img class="image-screensaver-poster" src="${sources[active]}" alt="趣味化 AI 体育锻炼图片屏保" draggable="false">${sources.length>1?`<div class="dots">${sources.map((_,i)=>`<i class="${i===active?'active':''}"></i>`).join('')}</div>`:''}</div>`}
function checkinKey(){return `${userId||'none'}:${C.day(now())}`}
function todayChecked(){if(!userId)return false;const key=checkinKey();return Object.hasOwn(checkinDemo,key)?checkinDemo[key]:records.some(r=>r.userId===userId&&C.day(r.timestamp)===C.day(now()))}
function setCheckinState(checked){if(!userId)return;checkinDemo[checkinKey()]=checked;log(`签到状态切换为${checked?'已签到':'未签到'}（模拟）`);render();toast(`已切换为${checked?'已签到':'未签到'}状态`)}
function homeView(){const checked=todayChecked();return `<div class="screen reference-home review-highlight"><img class="home-original" src="../../v1.0-home.png" alt="v1.0 首页原图：场地信息、三个人群入口、体态检测、健康百科、趣味锻炼、边看边学、排行榜" draggable="false"><button id="home-data" class="home-hotspot hotspot-profile" aria-label="我的数据"></button><button id="checkin" class="checkin-annotation review-new-feature ${checked?'is-checked':'is-unchecked'}" aria-label="${checked?'今日已签到，查看本月签到日历':'去签到，完成热身点亮今天'}">${checked?'✓ 已签到':'去签到'}</button><button class="home-hotspot hotspot-adult" data-audience="adult" aria-label="热力健将"></button><button class="home-hotspot hotspot-youth" data-audience="youth" aria-label="跃动少年"></button><button class="home-hotspot hotspot-senior" data-audience="senior" aria-label="康乐银发"></button>${calendarOpen?calendarView():''}</div>`}
function choose(id,origin='exercise'){chosen=C.catalog.find(c=>c.id===id);intent=origin;userId=null;authState='idle';navigate('guide');scheduleFace();log(`进入站位：${chosen?.name||(intent==='data'?'查看我的数据':'查看里程碑')}`)}
function calendarView(){const today=C.day(now()),[year,month]=today.split('-').map(Number);const count=new Date(Date.UTC(year,month,0)).getUTCDate(),offset=(new Date(Date.UTC(year,month-1,1)).getUTCDay()+6)%7;const prefix=today.slice(0,7),days=new Set(records.filter(r=>r.userId===userId).map(r=>C.day(r.timestamp)).filter(d=>d.startsWith(prefix)));if(todayChecked())days.add(today);else days.delete(today);return `<div class="medal-backdrop"><section class="medal-dialog checkin-calendar" role="dialog" aria-modal="true" aria-labelledby="calendar-title"><header><h2 id="calendar-title">本月运动签到</h2><button id="close-calendar" aria-label="关闭签到日历">×</button></header><div class="calendar-month">${year} 年 ${month} 月</div><div class="calendar-total">本月已签到 <b>${days.size}</b> 天</div><div class="calendar-week">${['一','二','三','四','五','六','日'].map(d=>'<span>'+d+'</span>').join('')}</div><div class="calendar-grid">${Array.from({length:offset},()=>'<span aria-hidden="true"></span>').join('')}${Array.from({length:count},(_,i)=>{const n=i+1,date=prefix+'-'+String(n).padStart(2,'0'),done=days.has(date),isToday=date===today;return `<div class="calendar-day ${done?'signed':''} ${isToday?'is-today':''} ${date>today?'future':''}" aria-label="${month}月${n}日${isToday?'，今天':''}，${done?'已签到':date>today?'未到日期':'未签到'}" ${isToday?'aria-current="date"':''}><b>${n}</b><small>${done?'✓':isToday?'今天':''}</small></div>`}).join('')}</div><div class="calendar-legend"><span>✓ 已签到</span><span><i></i> 今天</span></div><p class="calendar-note">完成一次运动，点亮当天</p></section></div>`}
function checkin(){if(todayChecked()){calendarOpen=true;render();D.querySelector('#close-calendar').focus();return}const warmup=C.catalog.find(c=>c.id==='warm');if(!warmup){toast('舒缓热身操暂不可用，请稍后重试');return}choose(warmup.id,'checkin')}
function scheduleFace(){clearTimeout(authTimer);userId=null;authState='idle';render();authTimer=setTimeout(()=>{if(screen==='guide')authenticate('face')},1000)}
function authenticate(method='face'){authMethod=method;if(method==='face'&&$('#identity').value==='failure'){authState='failed';render();log('人脸确认失败，等待调整站位后重新识别');return}if(!registered.has($('#person').value)&&authState!=='register-ready'){authState='new';render();return}userId=$('#person').value;registered.add(userId);authState='confirmed';render();log(`${method==='wechat'?'微信':'人脸'}确认：${names[userId]}`);autoStartTimer=setTimeout(()=>{if(screen==='guide'&&authState==='confirmed')startExercise()},900)}
function guideView(){const confirmed=authState==='confirmed';const checked=confirmed&&records.some(r=>r.userId===userId&&C.day(r.timestamp)===C.day(now()));let title=['milestones','data'].includes(intent)?'确认身份，查看积累':'请站在运动区域';let text='面向屏幕，让全身进入画面';let identity=`<strong>正在识别人脸，请看向摄像头</strong><p>站位时确认身份，运动记录会保存到你的账号。</p>`;let actions='';
if(authState==='failed'){identity='<strong>暂时没有识别成功</strong><p>请调整站位并看向摄像头，等待重新识别。</p>';actions=''}
if(authState==='new'){identity='<strong>欢迎第一次来运动</strong><p>继续完成现有注册与说明确认流程。</p><label class="confirm-check"><input type="checkbox" id="registration">已完成注册说明确认（演示）</label>';actions='<button class="primary" id="register" disabled>完成注册并继续</button>'}
if(confirmed){identity=`<strong>${names[userId]}，身份已确认</strong><p>${['data','milestones'].includes(intent)?'正在打开你的运动数据':checked?'今天已签到，即将开始运动':intent==='checkin'?'即将开始热身，完成后点亮今天':'已站好，即将开始运动'}</p>`;actions=''}
if(['milestones','data'].includes(intent))return `<div class="screen"><div class="back-row">${back()}</div><h2 class="page-title">${title}</h2><div class="guide-frame">${coach()}</div><div class="identity-card">${identity}</div>${actions}</div>`;
const ai=chosen?.type==='ai';return `<div class="screen preparation ${ai?'preparation-ai':'preparation-single'}">${ai?`<div class="teacher-preview"><h2>预备式</h2>${coach()}<span>教练示范 · 占位</span></div>`:''}<div class="camera-preview"><div class="camera-room"></div>${coach()}<div class="standing-zone"></div><div class="camera-hud"><div class="identity-pill"><span class="profile-dot">${confirmed?names[userId][0]:'人'}</span><div>${confirmed?names[userId]:'正在确认身份'}${!ai?`<small>${chosen.name}</small>`:''}</div></div><div class="score-pill">${!ai?`<span>${time(chosen.duration)}</span>`:''}<b>0</b>${ai?'<small>AI 打分</small>':''}</div></div><div class="position-hint">${confirmed?'身份已确认 · 请站好':'请站入绿色区域，看向摄像头'}</div><span class="camera-mock">摄像头画面示意</span></div><div class="preparation-auth"><div class="identity-card">${identity}</div><div class="preparation-actions">${actions}</div></div><div class="preparation-back">${back()}</div></div>`}
function startExercise(){if(!userId)return;if(intent==='data'){navigate('data');return}if(intent==='milestones'){milestoneReturn='home';navigate('milestones');return}session={id:`${Date.now()}-${++sequence}-${Math.random().toString(36).slice(2)}`,userId,courseId:chosen.id,type:chosen.type,intent};elapsed=0;paused=false;navigate('exercise');log(`本次运动绑定 ${names[userId]} / ${chosen.name}`)}
function exerciseView(){return `<div class="screen preparation exercise-active"><div class="teacher-preview"><h2>${chosen.name}</h2>${coach()}<span>教练示范</span></div><div class="camera-preview"><div class="camera-room"></div>${coach()}<div class="standing-zone"></div><div class="camera-hud"><div class="identity-pill"><span class="profile-dot">${names[session.userId][0]}</span><div>${names[session.userId]}<small>${chosen.name}</small></div></div><div class="score-pill"><span id="exercise-clock"></span><b id="exercise-score">0</b><small>AI 打分</small></div></div><div class="position-hint">AI 跟练进行中</div><div class="exercise-camera-progress"><i id="exercise-bar"></i></div><span class="camera-mock">摄像头画面示意</span></div></div>`}
function finish(reason){if(!session||screen!=='exercise')return;const seconds=reason==='normal'?chosen.duration:Number(elapsed.toFixed(3));const record={...session,seconds,kcal:num(chosen.kcal*seconds/chosen.duration),reason,timestamp:now()};const before=C.totals(records,record.userId);const had=records.some(r=>r.userId===record.userId&&C.day(r.timestamp)===C.day(record.timestamp));const result=C.settle(records,record,config.threshold);records=result.records;persist();lastReport={record,valid:result.valid,newCheckin:result.added&&!had,before,after:C.totals(records,record.userId)};feel=null;userId=record.userId;navigate('report');log(result.valid?'有效运动已结算；重复打开报告不再累计':'提前结束未达门槛，本次未计入')}
function progressCard(){const t=C.totals(records,userId);const checked=records.some(r=>r.userId===userId&&C.day(r.timestamp)===C.day(now()));const next=C.progress(t.days,C.levels.days);let note=next.next?`再运动 ${next.remaining} 天，解锁 ${next.next} 天里程碑`:'运动天数本阶段已完成，继续积累';if(lastReport?.valid){const b=lastReport.before,a=lastReport.after;const earned=C.levels.days.some(n=>b.days<n&&a.days>=n)||C.levels.kcal.some(n=>b.kcal<n&&a.kcal>=n)||C.levels.minutes.some(n=>b.seconds/60<n&&a.seconds/60>=n);if(earned)note='✦ 本次达成新里程碑，去看看你的积累'}return `<div class="growth-card"><div class="growth-head">${checked?'✓ 今日已签到':'今日尚未签到'}<span>${lastReport?.newCheckin&&lastReport.valid?'本次点亮今天':'签到与成长'}</span></div><div class="growth-metrics"><span><b>${t.days}</b>天</span><span><b>${num(t.kcal)}</b>千卡</span><span><b>${num(t.seconds/60)}</b>分钟</span></div><div class="growth-note">${note}</div><button class="growth-link" id="report-milestones">查看我的里程碑 →</button></div>`}
function metrics(r){return `<div class="metric-card"><div class="metric"><b>${r.type==='single'?Math.floor(r.seconds*1.5):num(r.kcal)}<small>${r.type==='single'?'次':'千卡'}</small></b><span>${r.type==='single'?'运动成绩':'运动消耗'}</span></div><div class="metric"><b>${r.type==='single'?num(r.kcal):time(r.seconds)}<small>${r.type==='single'?'千卡':''}</small></b><span>${r.type==='single'?'运动消耗':'运动时长'}</span></div><div class="metric"><b>${r.type==='single'?r.seconds:Math.floor(r.seconds/30)}<small>${r.type==='single'?'秒':'组'}</small></b><span>${r.type==='single'?'运动耗时':'完成动作'}</span></div></div>`}
function reportView(){if(!lastReport)return '<div class="screen"><h2>还没有运动报告</h2><button class="primary" data-go="home">返回首页</button></div>';const r=lastReport.record,c=C.catalog.find(c=>c.id===r.courseId);return `<div class="screen report review-highlight"><div class="report-head"><span class="avatar">${names[r.userId][0]}</span><span>${names[r.userId]}</span><b>${c.name}</b></div>${r.type==='single'?metrics(r):`<div class="ai-score"><span style="color:#e4a45c;font-size:16px">运动评分</span><b>${Math.min(95,Math.floor(r.seconds/c.duration*85))}</b><div class="stars">★ ★ ☆</div>${metrics(r)}</div>`}${!lastReport.valid?'<div class="invalid-note">本次未计入签到与累计进度<br><small>提前结束，未达到有效运动时长</small></div>':''}<div class="review-new-feature">${progressCard()}</div>${r.type==='single'?`<div class="chart-card"><div class="chart-title">运动曲线 <small>演示数据</small></div><svg viewBox="0 0 420 90"><path d="M0 20H420M0 50H420M0 80H420" stroke="#edf2f9"/><path d="M5 62Q55 20 105 36T205 52T305 32T415 38" fill="none" stroke="#4a83ef" stroke-width="4"/></svg></div><div class="chart-card" style="padding-bottom:28px"><div class="chart-title">近期成绩 <small>演示数据</small></div><div class="bar-chart">${[60,40,30,48,67].map((h,i)=>`<i style="height:${h}px" data-label="09/${i+1}"></i>`).join('')}</div></div>`:''}<div class="feeling"><span id="feeling-label">这次运动，感觉怎么样？</span><div class="feeling-buttons">${['轻松','稍累','累','很累','超累'].map((f,i)=>`<button data-feel="${i}" class="${feel===i?'selected':''}">${f}</button>`).join('')}</div></div><div class="report-actions"><button data-go="home">返回首页</button><button id="again">再来一次</button></div></div>`}
function milestoneView(){const t=displayTotals(userId),returnLabel=milestoneReturn==='data'?'返回我的数据':milestoneReturn==='report'?'返回运动报告':'返回首页',metrics=[['运动时长',num(t.seconds/60),'分钟',C.levels.minutes],['消耗热量',num(t.kcal),'千卡',C.levels.kcal],['运动天数',t.days,'天',C.levels.days]];return `<div class="screen milestone"><div class="milestone-heading"><h2>我的里程碑</h2><p>${names[userId]||'我的'} · 每一步，都算数</p></div><div class="milestone-medals">${metrics.map(([title,val,unit,steps])=>{const reached=steps.filter(n=>n<=val),best=reached.at(-1)||0,rank=reached.length;return `<div class="milestone-medal-state ${best?'earned':'pending'}"><div class="milestone-medal-art tier-${Math.min(rank,3)}">${medalIcon()}</div><small>${title}</small><strong>${best?best+' '+unit:'待点亮'}</strong></div>`}).join('')}</div>${metrics.map(([title,val,unit,steps])=>{const p=C.progress(val,steps);return `<div class="milestone-card"><h3>${title}<span>${val} ${unit}</span></h3><div class="milestone-track"><i style="width:${p.ratio*100}%"></i></div><div class="levels">${steps.map(n=>`<span class="${val>=n?'earned':''}">${val>=n?'✓ ':''}${n}</span>`).join('')}</div><p>${p.next?`距离 ${p.next} ${unit}，还差 ${num(p.remaining)} ${unit}`:'本阶段已完成，继续积累'}</p></div>`}).join('')}<p class="milestone-footer">休息几天也没关系，已有积累不会清零</p><button class="milestone-return" data-go="${milestoneReturn}">‹ ${returnLabel}</button></div>`}
function medalIcon(){return `<svg viewBox="0 0 48 56" aria-hidden="true"><path d="M10 1h11l7 22-11 5z" fill="#ff9a38"/><path d="M27 1h11L31 28l-11-5z" fill="#ffbe54"/><circle cx="24" cy="34" r="19" fill="#ffe3a1" stroke="#eab34a" stroke-width="2"/><path d="m24 21 4 8 9 1-7 6 2 9-8-5-8 5 2-9-7-6 9-1z" fill="#dc9a2e"/></svg>`}
function dataView(){const t=displayTotals(userId);const today=records.filter(r=>r.userId===userId&&C.day(r.timestamp)===C.day(now()));const mins=rs=>num(rs.reduce((n,r)=>n+r.seconds,0)/60);const mine=records.filter(r=>r.userId===userId);return `<div class="screen personal-data review-highlight ${dataMobile?'mobile-data':''}"><h2 class="data-place">上海三邻桥社区公园</h2><div class="data-user"><span class="data-avatar">${names[userId]?.[0]||'人'}</span><div><h2>${names[userId]||'我的数据'}</h2><p>UID ${userId==='chen'?'19******36':userId==='wang'?'19******28':'新用户'}</p></div>${!dataMobile?'<div class="data-qr"><span>▦</span><small>微信扫码<br>手机查看详情</small></div>':''}</div><div class="data-grid"><div class="data-card"><h3>今日运动</h3><div class="data-value">${mins(today)}<small>分钟</small></div><p>共消耗 <b>${num(today.reduce((n,r)=>n+r.kcal,0))}</b> 千卡</p></div><div class="data-card"><h3>累计运动</h3><button id="open-medals" class="medal-entry review-new-feature" aria-label="查看运动里程碑">${medalIcon()}</button><div class="data-value">${num(t.seconds/60)}<small>分钟</small></div><p>共消耗 <b>${num(t.kcal)}</b> 千卡</p></div>${dataMobile?'<div class="data-running"><h3>累计跑步 <span>— 公里</span></h3><p>最近一周</p><div class="running-empty">暂无跑步记录</div><div class="week-labels">周一　周二　周三　周四　今天　周六　周日</div></div>':''}<div class="data-card category physical"><h3>体能训练</h3><div class="data-value">${mins(mine.filter(r=>r.type==='single'))}<small>分钟</small></div></div><div class="data-card category leisure"><h3>休闲锻炼</h3><div class="data-value">—<small>分钟</small></div></div></div>${dataMobile?'<div class="data-tabs"><b>♙<span>我的数据</span></b><span>▤<small>运动记录</small></span></div>':'<div class="data-exit"><button class="secondary" id="logout">退出登录</button><p>60 秒未进行操作自动退出</p></div><div class="data-back">'+back()+'</div>'}</div>`}
function render(){cleanMedia();D.innerHTML=({data:dataView,video:videoView,image:imageView,home:homeView,guide:guideView,exercise:exerciseView,report:reportView,milestones:milestoneView}[screen])();$('#screen-label').textContent=screen==='data'?(dataMobile?'小程序 · 我的数据':'大屏 · 我的数据'):labels[screen];bindDevice();if(screen==='video')attachVideo();updateDynamic();updateInspector();updateRequirementsNote();resize()}
function bindDevice(){D.querySelectorAll('.goal-rail').forEach(rail=>{let drag=null;rail.onpointerdown=e=>{if(e.pointerType!=='mouse'||e.button!==0)return;drag={x:e.clientX,left:rail.scrollLeft};rail.setPointerCapture(e.pointerId)};rail.onpointermove=e=>{if(!drag)return;rail.scrollLeft=drag.left+(drag.x-e.clientX)*rail.clientWidth/rail.getBoundingClientRect().width};rail.onpointerup=rail.onpointercancel=()=>drag=null;rail.onlostpointercapture=()=>drag=null});D.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(b.dataset.go==='report'){userId=lastReport.record.userId}navigate(b.dataset.go)});const on=(id,fn)=>{const e=D.querySelector('#'+id);if(e)e.onclick=fn};on('close-calendar',()=>{calendarOpen=false;render();D.querySelector('#checkin').focus()});on('logout',()=>{userId=null;authState='idle';navigate('home')});on('open-medals',()=>{milestoneReturn='data';navigate('milestones')});on('previous',()=>nextItem(-1));on('next',()=>nextItem(1));on('retry-pool',()=>navigate('video'));on('start-preview',()=>{const id=current()?.id;if(id)choose(id)});on('sound',()=>{muted=!muted;const v=D.querySelector('video');if(v)v.muted=muted;D.querySelector('#sound').textContent=muted?'♪̸':'♪';D.querySelector('#sound').setAttribute('aria-label',`${muted?'开启':'关闭'}当前预览视频声音（不影响系统音量）`);D.querySelector('#sound').title=`${muted?'开启':'关闭'}当前预览视频声音，不影响系统音量`;if(!v)toast('当前为静态示意；导入视频后，此按钮仅控制当前预览声音')});on('checkin',checkin);on('home-data',()=>{dataMobile=false;choose(null,'data')});D.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>choose(b.dataset.course));D.querySelectorAll('[data-audience]').forEach(b=>b.onclick=()=>{cleanMedia();screen='video';activePool=C.catalog.filter(c=>c.audiences.includes(b.dataset.audience));idx=0;mediaFailed.clear();initPreview();log('按所选人群浏览运动内容')});on('view-milestones',()=>choose(null,'milestones'));const check=D.querySelector('#registration');if(check)check.onchange=()=>D.querySelector('#register').disabled=!check.checked;on('register',()=>{if(!check?.checked)return;authState='register-ready';authenticate(authMethod)});on('ready',startExercise);on('pause',()=>{paused=!paused;D.querySelector('#pause').textContent=paused?'继续运动':'暂停一下';updateInspector()});on('end-exercise',()=>finish('early'));on('report-milestones',()=>{milestoneReturn='report';navigate('milestones')});on('again',()=>choose(lastReport.record.courseId));D.querySelectorAll('[data-feel]').forEach(b=>b.onclick=()=>{feel=+b.dataset.feel;D.querySelectorAll('[data-feel]').forEach(x=>x.classList.toggle('selected',x===b));D.querySelector('#feeling-label').textContent=['很轻松，今天动得不错','稍微有点累，休息一下吧','辛苦了，按自己的节奏来','先休息一下吧','今天先到这里，休息一下吧'][feel]});on('image-background',e=>{if(e.target.closest('button'))return;navigate('home')})}
function attachVideo(){const v=D.querySelector('#preview-video'),c=current(),epoch=mediaEpoch;if(!v||!c)return;v.muted=muted;v.src=mediaURLs[c.id];let start=preview.start,initialized=false;const timeout=setTimeout(()=>{if(epoch===mediaEpoch&&!initialized)failMedia()},12000);v.onloadedmetadata=()=>{clearTimeout(timeout);if(epoch!==mediaEpoch)return;if(c.type==='single'){preview={start:0,end:v.duration,repeats:3}}else if(preview.end>v.duration){failMedia();return}v.currentTime=preview.start;v.playbackRate=Math.min(16,speed);initialized=true;v.play().catch(()=>toast('点击演示画面播放视频'));};v.onclick=()=>v.play().catch(()=>toast('视频无法播放，请更换素材'));v.onerror=()=>{clearTimeout(timeout);if(epoch===mediaEpoch)failMedia()};v.ontimeupdate=()=>{if(epoch!==mediaEpoch||!initialized)return;previewTime=Math.max(0,v.currentTime-preview.start);updateDynamic();if(c.type==='ai'&&v.currentTime>=preview.end)nextItem(1)};v.onended=()=>{if(epoch!==mediaEpoch)return;if(c.type==='ai'){nextItem(1);return}cycles++;if(cycles>=3){nextItem(1)}else{previewTime=0;v.currentTime=0;v.play().catch(()=>{})}}}
function tick(dt,manual=false){if(view!=='device'||(document.hidden&&!manual))return;if(screen==='video'&&preview&&current()){const video=D.querySelector('video');if(video){if(manual){video.currentTime=Math.min(preview.end,video.currentTime+dt)}return}previewTime+=dt;const len=preview.end-preview.start;if(previewTime>=len){previewTime=0;cycles++;if(cycles>=preview.repeats){nextItem(1);return}}}if(screen==='image'){imageTime+=dt;if(imageTime>=config.imageInterval){imageTime=0;imageIndex=(imageIndex+1)%(config.images.length||1);render()}}if(screen==='exercise'&&!paused){elapsed=Math.min(chosen.duration,elapsed+dt);if(elapsed>=chosen.duration){finish('normal');return}}updateDynamic()}
function updateDynamic(){if(screen==='video'&&preview&&current()){const len=preview.end-preview.start;const el=D.querySelector('#preview-caption');if(el)el.textContent=current().type==='single'?`演示 ${Math.min(cycles+1,3)} / 3 遍`:'30 秒精选片段';const clock=D.querySelector('#preview-clock');if(clock)clock.textContent=`${time(previewTime)} / ${time(len)}`;const bar=D.querySelector('#preview-bar');if(bar)bar.style.width=`${Math.min(100,previewTime/len*100)}%`}if(screen==='exercise'){D.querySelector('#exercise-clock').textContent=time(chosen.duration-elapsed);D.querySelector('#exercise-score').textContent=Math.min(95,Math.floor(elapsed/chosen.duration*85));D.querySelector('#exercise-bar').style.width=elapsed/chosen.duration*100+'%'}}
function reviewPageKey(){if(screen==='home'&&calendarOpen)return 'calendar';if(screen==='data')return dataMobile?'data-mobile':'data-screen';return screen}
function openReviewPage(key){const selected=$('#person')?.value||'chen',course=C.catalog.find(c=>c.id==='baduan')||C.catalog.find(c=>c.type==='ai')||C.catalog[0];clearTimeout(authTimer);logs=[];if(key==='video'||key==='image'){navigate(key);return}if(key==='home'){userId=selected;navigate('home');return}if(key==='calendar'){userId=selected;navigate('home');calendarOpen=true;render();return}if(key==='guide'){choose(course.id);return}if(key==='exercise'){chosen=course;userId=selected;registered.add(userId);session={id:`review-exercise-${Date.now()}`,userId,courseId:course.id,type:course.type,intent:'exercise'};elapsed=0;paused=false;navigate('exercise');return}if(key==='report'){chosen=course;userId=selected;registered.add(userId);const record={id:`review-report-${Date.now()}`,userId,courseId:course.id,type:course.type,intent:'exercise',seconds:course.duration,kcal:course.kcal,reason:'normal',timestamp:now()},totals=C.totals(records,userId);lastReport={record,valid:true,newCheckin:false,before:totals,after:totals};navigate('report');return}if(key==='data-screen'||key==='data-mobile'){dataMobile=key==='data-mobile';userId=selected;navigate('data');return}if(key==='milestones'){userId=selected;milestoneReturn='home';navigate('milestones')}}
function updateInspector(){const key=reviewPageKey(),meta=reviewPages.find(([id])=>id===key)||[key,'',labels[screen],0],c=current(),requirements=currentRequirements();$('#inspector-current-title').textContent=`${meta[1]} ${meta[2]}`;$('#inspector-change-count').textContent=`${meta[3]} 项变动`;$('#inspector-requirements-list').innerHTML=requirements.items.map(item=>`<li>${esc(item)}</li>`).join('');const checked=todayChecked();$('#checkin-unchecked')?.classList.toggle('active',!checked);$('#checkin-checked')?.classList.toggle('active',checked);document.querySelectorAll('[data-review-page]').forEach(b=>b.classList.toggle('active',b.dataset.reviewPage===key));document.querySelectorAll('.inspector [data-pages]').forEach(el=>el.classList.toggle('hidden',!el.dataset.pages.split(/\s+/).includes(key)));const notes={video:'仅显示预览速度、视频失败与空内容池控制。',image:'本页没有额外模拟参数，直接检查图片和轻触进入首页。',home:'可切换用户查看未签到／已签到状态。',calendar:'可切换用户或模拟下一天，检查本月签到分布。',guide:'可切换用户与人脸确认结果。',exercise:'可调整速度、推进时间或提前结束。',report:'可模拟下一天或重放同一报告，检查累计幂等。','data-screen':'可切换用户或模拟下一天，检查大屏个人数据。','data-mobile':'可切换用户或模拟下一天，检查小程序个人数据。',milestones:'可切换用户或模拟下一天，检查三个累计维度。'};$('#page-assumption-text').textContent=notes[key]||'';let detail=`${meta[2]} · ${C.day(now())}`;if(screen==='video'&&c&&preview)detail+=`<br>${c.name} · ${c.type==='single'?'完整播放 3 遍':`片段 ${time(preview.start)}—${time(preview.end)}`}`;if(screen==='data')detail+='<br>奖牌入口连接运动天数、热量和时长三种里程碑。';if(screen==='home')detail+=calendarOpen?'<br>展示当前用户本月有效运动签到。':'<br>签到入口区分未签到与已签到状态。';if(screen==='guide')detail+=`<br>身份：${userId?names[userId]:'尚未确认'} · ${intent==='checkin'?'热身签到':intent==='milestones'?'查看记录':'直接运动'}`;if(screen==='exercise'&&session)detail+=`<br>绑定 ${names[session.userId]} · ${paused?'暂停':'计时中'}`;if(screen==='report'&&lastReport)detail+=`<br>${lastReport.valid?'有效':'未计入'} · ${lastReport.record.seconds} 秒 · ${lastReport.record.kcal} 千卡`;$('#state-detail').innerHTML=detail;$('#event-log').innerHTML=logs.map(l=>`<div>· ${esc(l)}</div>`).join('')}
function currentRequirements(){if(screen==='video')return {title:'视频屏保',items:['运动预览视频铺满 9:16 屏幕，运动名称与操作按钮浮在画面上。','单项体能完整演示 3 遍后自动播放下一项；AI 跟练播放随机 30 秒片段后自动播放下一项。','点击两侧箭头或左右滑动浏览内容；点击“一键跟练”进入站位与身份确认。','声音按钮切换当前预览视频的声音，不调整设备系统音量。']};if(screen==='image')return {title:'图片屏保',items:['管理后台可配置最多 9 张屏保图片。','图片按设定间隔自动轮播。','轻触屏保画面进入设备首页。']};if(screen==='home'&&calendarOpen)return {title:'月度运动签到',items:['展示当前月份，并按周一至周日排列日期。','有效运动按上海时间自然日去重，区分已签到、今天和未来日期。','日期用于查看签到状态，关闭弹窗后返回设备首页。']};if(screen==='home')return {title:'设备首页',items:['顶部用户区域提供运动签到入口。','今日未签到显示“去签到”，完成签到后显示“✓ 已签到”。','点击“去签到”固定进入舒缓热身操；点击“✓ 已签到”查看本月签到日历。','三个人群卡片分别进入对应人群的运动内容。']};if(screen==='guide')return {title:'站位与身份确认',items:['进入运动前先引导用户站入绿色区域，并自动进行人脸确认。','已注册用户完成登录；新用户完成注册后继续。','身份确认后，将当前用户与本次运动记录绑定。','云端人脸服务不可用时，本地采集人脸并保存本次运动会话，联网后自动补传。']};if(screen==='exercise')return {title:'运动进行中',items:['开始运动后沿用站位阶段的 AI 跟练画面，并切换为计时和评分状态。','运动过程中支持提前结束；实际运动达到 10 秒后结束即按有效运动结算。','有效运动自动完成当日签到，运动记录归属于站位阶段确认的用户和运动项目。']};if(screen==='report')return {title:chosen?.type==='ai'?'AI 跟练报告':'单项体能报告',items:['结果报告展示本次成绩，并增加统一的简短进度卡。','有效运动自动完成当日签到。','运动天数按自然日累计，热量和运动时长按有效记录累计。']};if(screen==='data')return {title:dataMobile?'小程序 · 我的数据':'大屏 · 我的数据',items:['“累计运动”卡片右上角提供奖牌入口。','奖牌入口进入与 D08 共用的个人里程碑页面。','个人里程碑统一展示三个累计维度的升级进度。',dataMobile?'小程序展示当前已登录账号的个人数据。':'大屏完成人脸确认后展示当前账号的个人数据。']};return {title:'个人里程碑',items:['顶部并列展示三个维度的当前奖牌状态。','每个维度展示当前累计、最佳奖牌和后续升级目标。','页面只保留左下侧返回入口，便于不同身高的用户操作。']}}
