function mountAdminReview(){const host=$('#admin-view'),shell=host.querySelector('.legacy-admin-shell'),page=requirementGroups[1].pages.find(([,title])=>title===(adminPage==='heart'?'心率数据':'屏保管理')),title=page[1],items=page[2],code=page[0];host.classList.add('admin-review-workspace');const stage=document.createElement('div');stage.className='admin-stage-area';const frame=document.createElement('div');frame.className='admin-preview-frame';stage.append(frame);frame.append(shell);host.prepend(stage);host.insertAdjacentHTML('beforeend',`<aside class="inspector admin-review-inspector"><div class="inspector-head"><span class="eyebrow">PAGE REVIEW</span><h2>本页需求与演示</h2><p><span>${code} ${title}</span><b>${items.length} 项变动</b></p></div><div class="control-group current-page-requirements"><h3>本页需求</h3><ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div><div class="control-group"><h3>本页演示控制</h3>${adminPage==='screen'?'<div class="scenario-grid"><button data-admin-demo="video">运动视频配置</button><button data-admin-demo="image">图片配置</button></div><p class="admin-control-note">中间页面保留原有表单交互，可直接切换人群、推荐方式和内容顺序。</p>':'<p class="admin-control-note">当前展示心率数据无数据状态，本页无需额外模拟参数。</p>'}</div><div class="status-box"><span class="eyebrow">当前状态</span><p>${adminPage==='screen'?`屏保管理 · ${draft.mode==='video'?'运动视频屏保':'自定义图片屏保'}`:'心率数据 · 暂无配套设备数据'}</p></div></aside>`);document.querySelectorAll('[data-admin-page]').forEach(b=>b.classList.toggle('active',b.dataset.adminPage===adminPage));document.querySelectorAll('[data-admin-demo]').forEach(b=>b.onclick=()=>{draft.mode=b.dataset.adminDemo;renderExistingAdmin()})}
function rerenderExistingAdminAtScroll(focusSelector){const scroller=$('.admin-preview-frame')||$('.legacy-admin-shell'),scrollTop=scroller?.scrollTop||0;renderExistingAdmin();const nextScroller=$('.admin-preview-frame')||$('.legacy-admin-shell');if(nextScroller)nextScroller.scrollTop=scrollTop;if(focusSelector){const target=D.ownerDocument.querySelector(focusSelector);if(target)target.focus({preventScroll:true})}}
